        // EI_eff = D11 - B11² / A11
        EI_eff = D[0][0] - (B[0][0] * B[0][0]) / A[0][0];
    }

    return {
        "A" : A,
        "B" : B,
        "D" : D,
        "neutralAxisY" : neutralAxisY,
        "EI_eff" : EI_eff,
        "bodyContributions" : bodyContributions
    };
}

